digraph BankER {
// Entity style
node [shape=box,  fontcolor=black, fontsize=12];
// Entities
BANK [label="BANK", penwidth=1];
BRANCHES [label="BRANCHES", shape=diamond];
BANK_BRANCH [label="BANK_BRANCH", penwidth=3];
ACCTS [label="ACCTS", shape=diamond];
ACCOUNT [label="ACCOUNT"];
LOANS [label="LOANS", shape=diamond];
LOAN [label="LOAN"];
CUSTOMER [label="CUSTOMER"];
A_C [label="A_C", shape=diamond];
L_C [label="L_C", shape=diamond];
// Attributes (ellipses)
BANK_CODE [label="Code", shape=ellipse];
BANK_NAME [label="Name", shape=ellipse];
BANK_ADDR [label="Addr", shape=ellipse];
BRANCH_NO [label="Branch_no", shape=ellipse];
BRANCH_ADDR [label="Addr", shape=ellipse];
ACCT_NO [label="Acct_no", shape=ellipse];
BALANCE [label="Balance", shape=ellipse];
LOAN_NO [label="Loan_no", shape=ellipse];
AMOUNT [label="Amount", shape=ellipse];
ACCT_TYPE [label="Type", shape=ellipse];
LOAN_TYPE [label="Type", shape=ellipse];
CUSTOMER_SSN [label="Ssn", shape=ellipse];
CUSTOMER_NAME [label="Name", shape=ellipse];
CUSTOMER_PHONE [label="Phone", shape=ellipse];
CUSTOMER_ADDR [label="Addr", shape=ellipse];
// Relationships
BANK -> BANK_CODE [dir="none"];
BANK -> BANK_NAME [dir="none"];
BANK -> BANK_ADDR [dir="none"];
BANK_BRANCH -> BRANCH_NO [dir="none"];
BANK_BRANCH -> BRANCH_ADDR [dir="none"];
ACCOUNT -> ACCT_NO [dir="none"];
ACCOUNT -> BALANCE [dir="none"];
ACCOUNT -> ACCT_TYPE [dir="none"];
LOAN -> LOAN_NO [dir="none"];
LOAN -> AMOUNT [dir="none"];
LOAN -> LOAN_TYPE [dir="none"];
CUSTOMER -> CUSTOMER_SSN [dir="none"];
CUSTOMER -> CUSTOMER_NAME [dir="none"];
CUSTOMER -> CUSTOMER_PHONE [dir="none"];
CUSTOMER -> CUSTOMER_ADDR [dir="none"];
// Relationships between entities
BANK -> BRANCHES [];
BRANCHES -> BANK_BRANCH [penwidth=2, dir="none"];
BANK_BRANCH -> ACCTS [label="1", dir="none"];
ACCTS -> ACCOUNT [label="N", dir="none"];
BANK_BRANCH -> LOANS [label="1", dir="none"];
LOANS -> LOAN [label="N", dir="none"];
ACCOUNT -> A_C [label="M", dir="none"];
A_C -> CUSTOMER [label="N", dir="none"];
LOAN -> L_C [label="M", dir="none"];
L_C -> CUSTOMER [label="N", dir="none"];
}
